PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    MotorLatch : BOOL := FALSE;
    EmergencyTimer : TON;
END_VAR

// Check for emergency stop activation
IF NOT EStop THEN
    // If emergency stop is activated, de-energize the motor and clear the latch
    MotorLatch := FALSE;
    Motor := FALSE;
    EmergencyTimer(IN := TRUE, PT := T#0s);
ELSE
    // If emergency stop is not activated, check Start and Stop buttons
    IF Start AND NOT Stop AND NOT MotorLatch THEN
        // Latch on Start if not stopped and not already running
        MotorLatch := TRUE;
        Motor := TRUE;
    ELSIF Stop THEN
        // Clear the latch on Stop
        MotorLatch := FALSE;
        Motor := FALSE;
    ELSE
        // Hold the state if neither button is pressed
        Motor := MotorLatch;
    END_IF;
END_IF;

// Ensure Motor is off if EStop is activated
Motor := NOT EStop AND Motor;

END_PROGRAM

PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    Motor_Latched : BOOL := FALSE;
    Emergency_Stopped : BOOL := FALSE;
END_VAR

// Check if the emergency stop is activated
Emergency_Stopped := NOT EStop;

// If the emergency stop is activated, turn off the motor and clear the latch
IF Emergency_Stopped THEN
    Motor := FALSE;
    Motor_Latched := FALSE;
ELSIF Start AND NOT Motor_Latched THEN
    // Start button press and motor not already latched
    Motor_Latched := TRUE;
ELSIF Stop OR Emergency_Stopped THEN
    // Stop button press or emergency stop activates
    Motor_Latched := FALSE;
END_IF;

// Assign the final state of the motor
Motor := Motor_Latched;

END_PROGRAM

