PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    last_pump_state : BOOL := FALSE;
    last_valve_state : BOOL := FALSE;
END_VAR

IF NOT last_pump_state AND (Level <= 10 OR Level >= 90) THEN
    last_pump_state := TRUE;
END_IF;

IF last_pump_state AND Level > 10 AND Level < 90 THEN
    last_pump_state := FALSE;
END_IF;

PumpIn := last_pump_state AND NOT (Level >= 90);

IF Level >= 90 THEN
    ValveOut := TRUE;
ELSE
    ValveOut := FALSE;
END_IF;

last_valve_state := ValveOut;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    prev_pump_state : BOOL := FALSE;
END_VAR

// Check if the level is at or above the high limit (90%)
IF Level >= 90 THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= 10 THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := prev_pump_state;
    ValveOut := FALSE;
END_IF;

prev_pump_state := PumpIn;
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    last_pump_state : BOOL := FALSE;
    last_valve_state : BOOL := FALSE;
END_VAR

// Define hysteresis limits
CONSTANT low_limit : INT := 10;
CONSTANT high_limit : INT := 90;

// Check if the pump state has changed
IF PumpIn <> last_pump_state THEN
    last_pump_state := PumpIn;
END_IF;

// Check if the valve state has changed
IF ValveOut <> last_valve_state THEN
    last_valve_state := ValveOut;
END_IF;

// Control the pump and valve based on the level
IF Level <= low_limit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSIF Level >= high_limit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    prev_PumpIn : BOOL := FALSE;
    prev_ValveOut : BOOL := FALSE;
    Level_Low : INT := 10;
    Level_High : INT := 90;
    Level_Tolerance : INT := 5;
END_VAR

// Check if the level is within the tolerance band
IF (Level >= Level_Low - Level_Tolerance) AND (Level <= Level_High + Level_Tolerance) THEN
    // If the level is within the tolerance, maintain previous states
    PumpIn := prev_PumpIn;
    ValveOut := prev_ValveOut;
ELSE
    // If the level is outside the tolerance, adjust the pump and valve states
    IF Level <= Level_Low THEN
        PumpIn := TRUE;
        ValveOut := FALSE;
    ELSIF Level >= Level_High THEN
        PumpIn := FALSE;
        ValveOut := TRUE;
    ELSE
        PumpIn := FALSE;
        ValveOut := FALSE;
    END_IF;
END_IF;

// Update previous states for the next cycle
prev_PumpIn := PumpIn;
prev_ValveOut := ValveOut;
END_PROGRAM

