    prev_valve_out : BOOL := FALSE;
    hysteresis_high : TON;
    hysteresis_low : TON;
END_VAR

hysteresis_high(IN := Level >= 90, PT := T#0s);
hysteresis_low(IN := Level <= 10, PT := T#0s);

IF NOT hysteresis_high.Q THEN
    PumpIn := TRUE;
ELSE
    PumpIn := FALSE;
END_IF;

IF hysteresis_high.Q THEN
    ValveOut := TRUE;
ELSE
    ValveOut := FALSE;
END_IF;

IF PumpIn AND hysteresis_high.Q THEN
    PumpIn := FALSE;
END_IF;

prev_pump_in := PumpIn;
prev_valve_out := ValveOut;
END_PROGRAM

PROGRAM tank_level
