VAR
    PumpInLast : BOOL := FALSE;
    T#_PumpDelay : TON;
END_VAR

T#_PumpDelay(IN := NOT PumpIn AND NOT PumpInLast, PT := T#2s);

IF Level <= 10 THEN
    PumpIn := TRUE;
    PumpInLast := TRUE;
    ValveOut := FALSE;
ELSIF Level >= 90 THEN
    PumpIn := FALSE;
    PumpInLast := FALSE;
    ValveOut := TRUE;
ELSIF NOT T#_PumpDelay.Q THEN
    PumpIn := FALSE;
    PumpInLast := FALSE;
    ValveOut := FALSE;
ELSE
    PumpIn := FALSE;
    PumpInLast := FALSE;
    ValveOut := FALSE;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    prev_pump_in : BOOL := FALSE;
    prev_valve_out : BOOL := FALSE;
END_VAR

// Define hysteresis limits
CONSTANT
    low_limit : INT := 10;
    high_limit : INT := 90;
END_CONSTANT

// Check if the level has changed significantly to avoid oscillation
IF NOT(prev_pump_in = PumpIn AND prev_valve_out = ValveOut) THEN
    // Turn on the inlet pump if the level is below the low limit and off if it's above the high limit
    IF Level <= low_limit THEN
        PumpIn := TRUE;
    ELSIF Level >= high_limit THEN
        PumpIn := FALSE;
    ELSE
        PumpIn := FALSE;
    END_IF;

    // Always open the outlet valve if the level is at or above the high limit
    IF Level >= high_limit THEN
        ValveOut := TRUE;
    ELSE
        ValveOut := FALSE;
    END_IF;

    // Update previous states
    prev_pump_in := PumpIn;
    prev_valve_out := ValveOut;
END_IF;
END_PROGRAM

PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    DoorA_Latched : BOOL := FALSE;
    DoorB_Latched : BOOL := FALSE;
    DoorA_Timer : TON;
    DoorB_Timer : TON;
END_VAR

// Check if Door A should open
IF OpenA_Cmd AND NOT DoorB_Latched THEN
    DoorA_Latched := TRUE;
    DoorB_Latched := FALSE;
    DoorA_Timer(IN := TRUE, PT := T#0s);
ELSE
    DoorA_Latched := FALSE;
    DoorA_Timer(IN := FALSE);
END_IF;

// Check if Door B should open
IF OpenB_Cmd AND NOT DoorA_Latched THEN
    DoorB_Latched := TRUE;
    DoorA_Latched := FALSE;
    DoorB_Timer(IN := TRUE, PT := T#0s);
ELSE
    DoorB_Latched := FALSE;
    DoorB_Timer(IN := FALSE);
END_IF;

// Assign output states based on latching and timers
DoorA := DoorA_Latched AND NOT DoorB_Latched;
DoorB := DoorB_Latched AND NOT DoorA_Latched;

END_PROGRAM

PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    DoorA_Req : BOOL := FALSE;
    DoorB_Req : BOOL := FALSE;
    DoorATimer : TON;
    DoorBTimer : TON;
END_VAR

// Check if either door is requested open and assign requests
DoorA_Req := OpenA_Cmd AND NOT DoorB;
DoorB_Req := OpenB_Cmd AND NOT DoorA;

// Clear outputs initially
DoorA := FALSE;
DoorB := FALSE;

// Handle Door A opening
IF DoorA_Req THEN
    DoorA := TRUE;
    DoorATimer(IN := TRUE, PT := T#0s);
ELSE
    IF DoorATimer.Q THEN
        DoorA := FALSE;
    END_IF;
END_IF;

// Handle Door B opening
IF DoorB_Req THEN
    DoorB := TRUE;
    DoorBTimer(IN := TRUE, PT := T#0s);
ELSE
    IF DoorBTimer.Q THEN
        DoorB := FALSE;
    END_IF;
END_IF;

END_PROGRAM

PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    DoorA_Latched : BOOL := FALSE;
    DoorB_Latched : BOOL := FALSE;
    PriorityTimer : TON;
END_VAR

// Check for conflicting commands
IF OpenA_Cmd AND NOT OpenB_Cmd THEN
    DoorA_Latched := TRUE;
    DoorB_Latched := FALSE;
    PriorityTimer(IN := TRUE, PT := T#0s);
ELSIF NOT OpenA_Cmd AND OpenB_Cmd THEN
    DoorA_Latched := FALSE;
    DoorB_Latched := TRUE;
    PriorityTimer(IN := TRUE, PT := T#0s);
ELSE
    PriorityTimer(IN := FALSE);
END_IF;

// Apply latching and priority rules
IF PriorityTimer.Q AND DoorA_Latched THEN
    DoorA := TRUE;
    DoorB := FALSE;
ELSIF PriorityTimer.Q AND DoorB_Latched THEN
    DoorA := FALSE;
    DoorB := TRUE;
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
END_IF;

END_PROGRAM

