VAR
    DoorA_Req : BOOL := FALSE;
    DoorB_Req : BOOL := FALSE;
    DoorATimer : TON;
    DoorBTimer : TON;
END_VAR

// Update request flags based on input commands
DoorA_Req := OpenA_Cmd AND NOT DoorB;
DoorB_Req := OpenB_Cmd AND NOT DoorA;

// Check if either door can open
IF DoorA_Req THEN
    DoorA := TRUE;
    DoorB := FALSE;
    DoorATimer(IN := TRUE, PT := T#0s);
    DoorBTimer(IN := FALSE, PT := T#0s);
ELSIF DoorB_Req THEN
    DoorA := FALSE;
    DoorB := TRUE;
    DoorATimer(IN := FALSE, PT := T#0s);
    DoorBTimer(IN := TRUE, PT := T#0s);
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
    DoorATimer(IN := FALSE, PT := T#0s);
    DoorBTimer(IN := FALSE, PT := T#0s);
END_IF;

// Priority check
IF DoorA AND DoorB THEN
    DoorA := TRUE;
    DoorB := FALSE;
END_IF;

END_PROGRAM

