PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    NS_green, NS_yellow, NS_allred, EW_green, EW_yellow, EW_allred : TON;
END_VAR;

NS_green(IN := State = 0, PT := T#2s);
NS_yellow(IN := State = 1, PT := T#1s);
NS_allred(IN := State = 2, PT := T#1s);
EW_green(IN := State = 3, PT := T#2s);
EW_yellow(IN := State = 4, PT := T#1s);
EW_allred(IN := State = 5, PT := T#1s);

CASE State OF
    0:
        NS_G := TRUE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    1:
        NS_G := FALSE;
        NS_Y := TRUE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    2:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    3:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := TRUE;
        EW_Y := FALSE;
        EW_R := FALSE;
    4:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := TRUE;
        EW_R := FALSE;
    5:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
END_CASE;

IF NOT NS_green.Q AND NOT NS_yellow.Q AND NOT NS_allred.Q THEN
    State := State + 1;
    IF State > 5 THEN
        State := 0;
    END_IF;
END_IF;

IF NOT EW_green.Q AND NOT EW_yellow.Q AND NOT EW_allred.Q THEN
    State := State + 1;
    IF State > 5 THEN
        State := 0;
    END_IF;
END_IF;
END_PROGRAM

PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    TNSGreen, TEWGreen, TAllRed : TON;
END_VAR

CASE State OF
    0 :
        TNSGreen(IN := TRUE, PT := T#2s);
        TEWGreen(IN := FALSE, PT := T#0s);
        TAllRed(IN := FALSE, PT := T#0s);
        NS_G := TRUE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;

    1 :
        TNSGreen(IN := FALSE, PT := T#0s);
        TEWGreen(IN := FALSE, PT := T#0s);
        TAllRed(IN := FALSE, PT := T#0s);
        NS_G := FALSE;
        NS_Y := TRUE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;

    2 :
        TNSGreen(IN := FALSE, PT := T#0s);
        TEWGreen(IN := FALSE, PT := T#0s);
        TAllRed(IN := TRUE, PT := T#1s);
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;

    3 :
        TNSGreen(IN := FALSE, PT := T#0s);
        TEWGreen(IN := TRUE, PT := T#2s);
        TAllRed(IN := FALSE, PT := T#0s);
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := TRUE;
        EW_Y := FALSE;
        EW_R := FALSE;

    4 :
        TNSGreen(IN := FALSE, PT := T#0s);
