        MotorUp := FALSE;
        MotorDown := FALSE;
        IF CallDown AND DoorClosed THEN
            State := 3;
            MoveTimer(IN := TRUE, PT := T#3s);
        END_IF;

    3: // Moving-down
        MotorUp := FALSE;
        MotorDown := TRUE;
        IF AtBottom OR NOT CallDown THEN
            State := 0;
            MoveTimer(IN := FALSE);
        ELSIF NOT DoorClosed THEN
            State := 0;
            MoveTimer(IN := FALSE);
        END_IF;
END_CASE;

IF MoveTimer.Q THEN
    MoveTimer(IN := FALSE);
