    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR

VAR
    State : INT := 0;
    T_ReactTimer : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
    T_ReactTimer(IN := FALSE);
END_IF;

CASE State OF
    0: // Idle
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1: // Fill
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;

        IF Level >= LVL_HIGH THEN
            State := 2;
        END_IF;

    2: // Heat
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;

        IF Temp >= TEMP_SET THEN
            State := 3;
        END_IF;

    3: // React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;

        T_ReactTimer(IN := TRUE, PT := PT_REACT);

        IF NOT T_ReactTimer.Q THEN
            State := 4;
        END_IF;

    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;

        IF Level <= LVL_LOW THEN
            State := 0;
        END_IF;
END_CASE;

// Safety checks
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

IF Level < LIQ_MIN AND (Heater OR Agitator) THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR_CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR

VAR
    State : INT := 0;
    T_HeatTimer : TON;
END_VAR

EStop := NOT EStop;

CASE State OF
    0: // Idle
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF StartBatch AND EStop THEN
            State := 1;
        END_IF;

    1: // Fill
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF Level >= LVL_HIGH OR NOT EStop THEN
            FillValve := FALSE;
            State := 2;
        END_IF;

    2: // Heat
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        T_HeatTimer(IN := EStop, PT := PT_REACT);
        IF NOT EStop OR T_HeatTimer.Q THEN
            Heater := FALSE;
            Agitator := FALSE;
            State := 3;
        END_IF;

    3: // React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        T_HeatTimer(IN := EStop, PT := PT_REACT);
        IF NOT EStop OR T_HeatTimer.Q THEN
            Heater := FALSE;
            Agitator := FALSE;
            State := 4;
        END_IF;

    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
        IF Level <= LVL_LOW OR NOT EStop THEN
            DrainValve := FALSE;
            State := 0;
        END_IF;
END_CASE;

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

END_PROGRAM

