PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR

VAR
    State : INT := 0;
    FillTimer : TON;
    DrainTimer : TON;
END_VAR

CASE State OF
    0: // Idle
        Pump := FALSE;
        Valve := FALSE;
        IF EStop THEN
            State := 0;
        ELSIF StartCycle AND Level < 90 THEN
            State := 1;
        END_IF;

    1: // Filling
        Pump := TRUE;
        Valve := FALSE;
        IF EStop OR Level >= 90 THEN
            State := 2;
        END_IF;

    2: // Draining
        Pump := FALSE;
        Valve := TRUE;
        IF EStop OR Level <= 10 THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR

VAR
    State : INT := 0;
    FillTimer : TON;
    DrainTimer : TON;
END_VAR

CASE State OF
    0: // Idle
        Pump := FALSE;
        Valve := FALSE;
        IF StartCycle AND NOT EStop THEN
            IF Level < 90 THEN
                State := 1;
                FillTimer(IN := TRUE, PT := T#0s);
            END_IF;
        END_IF;

    1: // Filling
        Pump := TRUE;
        Valve := FALSE;
        IF Level >= 90 OR EStop THEN
            State := 2;
            DrainTimer(IN := TRUE, PT := T#0s);
        END_IF;

    2: // Draining
        Pump := FALSE;
        Valve := TRUE;
        IF Level <= 10 OR EStop THEN
            State := 0;
        END_IF;
END_CASE;

// Safety conditions
IF EStop THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
END_IF;

// Prevent both pump and valve from being on simultaneously
IF Pump AND Valve THEN
    Pump := FALSE;
    Valve := FALSE;
END_IF;

// Ensure pump does not run at/above HIGH
IF Pump AND Level >= 90 THEN
    Pump := FALSE;
END_IF;

// Ensure valve is never open at/below LOW
IF Valve AND Level <= 10 THEN
    Valve := FALSE;
END_IF;

END_PROGRAM

