    T_Purge : TON;
    T_Ignition : TON;
END_VAR

CASE State OF
    0: // Off
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF StartPB AND NOT EStop THEN
            State := 1;
            T_Purge(IN := TRUE, PT := T#3s);
        END_IF;

    1: // Purge
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF T_Purge.Q THEN
            State := 2;
            T_Ignition(IN := TRUE, PT := T#2s);
        END_IF;

    2: // Ignition Trial
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF T_Ignition.Q THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;

    3: // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR EStop OR StopPB THEN
            State := 0;
        END_IF;
END_CASE;

// Safety check: Fuel valve must not be open unless fan is running
Fuel := Fuel AND Fan;

// Safety check: Igniter must only be on with fuel present
Ignition := Ignition AND Fuel;

END_PROGRAM

