    PrevDemand : BOOL := FALSE;
END_VAR

// Edge detection for Demand
PrevDemand := Demand;

// Check if EStop is activated
IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
    EXIT;
END_IF;

// Alternate lead when Demand ends
IF NOT Demand AND PrevDemand THEN
    Lead := 1 - Lead; // Toggle Lead
END_IF;

// Assign pumps based on Lead
CASE Lead OF
    0:
        Pump1 := Demand;
        Pump2 := FALSE;
    1:
        Pump1 := FALSE;
        Pump2 := Demand;
    ELSE
        Pump1 := FALSE;
        Pump2 := FALSE;
END_CASE;

