PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    EdgeDetected : BOOL := FALSE;
END_VAR

// Detect falling edge of Demand
EdgeDetected := NOT PrevDemand AND Demand;

// Check if EStop is activated
IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
    Lead := 0; // Reset lead state on EStop
    PrevDemand := FALSE; // Reset previous demand
ELSE
    IF EdgeDetected THEN
        // Alternate lead state on falling edge of Demand
        Lead := 1 - Lead;
        PrevDemand := TRUE; // Update previous demand
    ELSIF NOT Demand THEN
        // Hold the previous demand state when Demand ends
        PrevDemand := TRUE;
    ELSE
        // Clear previous demand state when Demand starts
        PrevDemand := FALSE;
    END_IF;

    // Assign pumps based on lead state
    CASE Lead OF
        0:
            Pump1 := Demand;
            Pump2 := FALSE;
        1:
            Pump1 := FALSE;
            Pump2 := Demand;
    END_CASE;
END_IF;

END_PROGRAM

