END_VAR

// Detect falling edge of Demand
PrevDemand := Demand;

// Check for emergency stop
IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
    Lead := 0; // Reset lead after EStop
END_IF;

// Check if demand has ended (falling edge)
IF PrevDemand AND NOT Demand THEN
    Lead := 1 - Lead; // Toggle lead
END_IF;

// Control pumps based on demand and lead state
CASE Lead OF
    0: Pump1 := Demand; Pump2 := FALSE;
    1: Pump1 := FALSE; Pump2 := Demand;
END_CASE;

// Ensure only one pump runs when there is demand
IF Demand THEN
    PumpTimer(IN := TRUE, PT := T#1s);
    IF PumpTimer.Q THEN
        Pump1 := FALSE;
        Pump2 := FALSE;
    END_IF;
END_IF;

