// Check if Demand has fallen (Estop or Demand off)
IF NOT EStop OR NOT Demand THEN
    // Clear timers and set previous demand state
    PumpTimer(IN := FALSE);
    PrevDemand := FALSE;
END_IF;

// Alternate lead on falling edge of Demand
IF NOT PrevDemand AND Demand THEN
