END_IF;

// Assign pumps based on Lead and EStop status
CASE Lead OF
    0:
        Pump1 := Demand AND EStop;
        Pump2 := FALSE;
    1:
        Pump2 := Demand AND EStop;
        Pump1 := FALSE;
END_CASE;

