PROGRAM gate
VAR_INPUT
    OpenCmd : BOOL;
    CloseCmd : BOOL;
    OpenLimit : BOOL;
    CloseLimit : BOOL;
    Obstruction : BOOL;
END_VAR

VAR_OUTPUT
    MotorOpen : BOOL;
    MotorClose : BOOL;
END_VAR

VAR
    State : INT := 0;
    OpeningTimer : TON;
    ClosingTimer : TON;
END_VAR

CASE State OF
    0: // Idle
        MotorOpen := FALSE;
        MotorClose := FALSE;
        IF OpenCmd AND NOT OpenLimit THEN
            State := 1;
            OpeningTimer(IN := TRUE, PT := T#5s);
        ELSIF CloseCmd AND NOT (CloseLimit OR Obstruction) THEN
            State := 2;
            ClosingTimer(IN := TRUE, PT := T#5s);
        END_IF;

    1: // Opening
        MotorOpen := TRUE;
        MotorClose := FALSE;
        IF OpenLimit THEN
            State := 0;
        ELSIF Obstruction THEN
            State := 0;
        ELSIF NOT OpeningTimer.Q THEN
            State := 0;
        END_IF;

    2: // Closing
        MotorOpen := FALSE;
        MotorClose := TRUE;
        IF CloseLimit THEN
            State := 0;
        ELSIF Obstruction THEN
            State := 0;
        ELSIF NOT ClosingTimer.Q THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

